package io.github.ranger3462.dungeondelving.dungeon;

import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.level.storage.loot.predicates.LootItemCondition;
import net.neoforged.neoforge.common.loot.IGlobalLootModifier;
import net.neoforged.neoforge.common.loot.LootModifier;

/**
 * Marks everything generated by any loot table in the dungeon dimension (chests, mob drops, block drops) as dungeon
 * loot. Registered for all loot tables in {@code data/neoforge/loot_modifiers/global_loot_modifiers.json}.
 */
public class TagDungeonLootModifier extends LootModifier {
    public static final MapCodec<TagDungeonLootModifier> CODEC =
            RecordCodecBuilder.mapCodec(instance -> codecStart(instance).apply(instance, TagDungeonLootModifier::new));

    public TagDungeonLootModifier(LootItemCondition[] conditions) {
        super(conditions);
    }

    @Override
    protected ObjectArrayList<ItemStack> doApply(ObjectArrayList<ItemStack> generatedLoot, LootContext context) {
        DungeonLoot.markIfInDungeon(generatedLoot, context.getLevel().dimension());
        return generatedLoot;
    }

    @Override
    public MapCodec<? extends IGlobalLootModifier> codec() {
        return CODEC;
    }
}
